import{a as e,c as t,i as n}from"./app-DoNgtmw6.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-23-daemon-runtime.html","title":"Docker Daemon 与 runtime——一条 docker run 经过了谁的手","lang":"zh-CN","frontmatter":{"title":"Docker Daemon 与 runtime——一条 docker run 经过了谁的手","sidebarGroup":"Docker 系列","shortTitle":"23 Daemon 与 runtime","order":23,"date":"2026-08-25T00:00:00.000Z","category":"云原生","tag":["Docker","云原生","Docker系列","OCI","containerd","runc","CRI","对话实录"],"description":"师生对话实录课：0 基础学生与教学大师的 runtime 链路逐字稿。从「升级 dockerd 会不会杀死全部容器」的悬念出发，在本机实拍 dockerd/containerd/shim/runc 家族进程树，亲手打开 OCI 合同（runc spec）、验证 runtime 状态机（docker create 的 Created）、用 ctr 从 containerd 视角看到 moby 命名空间，最后讲清 K8s 弃用的 dockershim 到底是什么。","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Docker Daemon 与 runtime——一条 docker run 经过了谁的手\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2026-08-25T00:00:00.000Z\\",\\"dateModified\\":\\"2026-08-25T13:00:27.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"Corey\\",\\"url\\":\\"https://www.code-corey.com\\"}]}"],["meta",{"property":"og:url","content":"https://www.code-corey.com/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-23-daemon-runtime.html"}],["meta",{"property":"og:site_name","content":"Corey 知识库"}],["meta",{"property":"og:title","content":"Docker Daemon 与 runtime——一条 docker run 经过了谁的手"}],["meta",{"property":"og:description","content":"师生对话实录课：0 基础学生与教学大师的 runtime 链路逐字稿。从「升级 dockerd 会不会杀死全部容器」的悬念出发，在本机实拍 dockerd/containerd/shim/runc 家族进程树，亲手打开 OCI 合同（runc spec）、验证 runtime 状态机（docker create 的 Created）、用 ctr 从 containerd 视角看到 moby 命名空间，最后讲清 K8s 弃用的 dockershim 到底是什么。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-08-25T13:00:27.000Z"}],["meta",{"property":"article:tag","content":"对话实录"}],["meta",{"property":"article:tag","content":"CRI"}],["meta",{"property":"article:tag","content":"runc"}],["meta",{"property":"article:tag","content":"containerd"}],["meta",{"property":"article:tag","content":"OCI"}],["meta",{"property":"article:tag","content":"Docker系列"}],["meta",{"property":"article:tag","content":"云原生"}],["meta",{"property":"article:tag","content":"Docker"}],["meta",{"property":"article:published_time","content":"2026-08-25T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-08-25T13:00:27.000Z"}]]},"git":{"createdTime":1786673091000,"updatedTime":1787662827000,"contributors":[{"name":"chengongyi","username":"chengongyi","email":"2363613998@qq.com","commits":7,"url":"https://github.com/chengongyi"},{"name":"Cursor","username":"Cursor","email":"cursoragent@cursor.com","commits":1,"url":"https://github.com/Cursor"},{"name":"Corey C","username":"","email":"2363613998@qq.com","commits":1},{"name":"Claude","username":"Claude","email":"noreply@anthropic.com","commits":1,"url":"https://github.com/Claude"}]},"readingTime":{"minutes":20.12,"words":6036},"filePathRelative":"云原生/docker/docker-23-daemon-runtime.md","excerpt":"<blockquote>\\n<p><strong>Docker 系列 · 第 23/33 篇</strong><br>\\n上一篇：<a href=\\"/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-22-unionfs\\">《从零理解 Docker 镜像分层——两个目录叠出一个文件系统（师生对话实录）》</a> · 下一篇：<a href=\\"/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-24-process-view\\">《进程视角看容器——从两边 ps 对不上号，滚到亲手杀掉 PID 1》</a></p>\\n<p>阶段 6「内幕」的架构主线：第 20 篇拆了 Namespace、第 22 篇拆了镜像分层，这篇把整条执行链 CLI → dockerd → containerd → shim → runc 按职责拆开——下一篇再回到进程树上排障。</p>\\n</blockquote>"}`),a={name:`docker-23-daemon-runtime.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<blockquote><p><strong>Docker 系列 · 第 23/33 篇</strong><br> 上一篇：<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-22-unionfs">《从零理解 Docker 镜像分层——两个目录叠出一个文件系统（师生对话实录）》</a> · 下一篇：<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-24-process-view">《进程视角看容器——从两边 ps 对不上号，滚到亲手杀掉 PID 1》</a></p><p>阶段 6「内幕」的架构主线：第 20 篇拆了 Namespace、第 22 篇拆了镜像分层，这篇把整条执行链 CLI → dockerd → containerd → shim → runc 按职责拆开——下一篇再回到进程树上排障。</p></blockquote><hr><h2 id="写在前面" tabindex="-1"><a class="header-anchor" href="#写在前面"><span>写在前面</span></a></h2><p>学到第 23 篇，容器「是什么」已经拆透了，但两个很现实的问题我答不上来：</p><ol><li>机器要升级 Docker 版本，<code>systemctl restart docker</code> 敲下去之前犹豫半天——上面十几个正在跑的容器，会不会跟着全没？</li><li>在宿主机 <code>ps -ef</code>，看到一排 <code>containerd-shim-runc-v2</code> 进程，不知道是谁起的、能不能杀。</li></ol><p>答不上来，是因为不清楚 <code>docker run</code> 背后不是一个人在干活，而是五级调用在接力。所以这篇继续用老办法：<strong>让 AI 当老师，我当学生，每课只讲一个概念，有问题就打断，没问题就继续</strong>。全文只用一条命令当线索——<code>docker run -d busybox sleep 600</code>——看它到底经过了谁的手。</p><p>课程路线图（走到哪算哪）：</p><blockquote><p>① 实拍家族进程树 → ② 装一个 Docker 来了一家人 → ③ CLI 只发令 → ④ dockerd 接单记账 → ⑤ OCI 合同与 bundle → ⑥ 上半页 image-spec → ⑦ 下半页 runtime-spec 状态机 → ⑧ containerd 大管家 → ⑨ shim 陪跑与 daemon 重启悬念 → ⑩ runc 动手 + 全景拼图 → ⑪ CRI：K8s 弃用的到底是什么</p></blockquote><p>环境：WSL2 Ubuntu-22.04（root）· Docker Engine 29.1.3 · containerd（独立 systemd 服务）· runc 1.3.4（实现 runtime-spec 1.2.1）。全部进程树与命令输出为本机 2026-08-25 实拍——这篇的老版本借用过别人实验机的输出，这次全部换成自己机器的真实现场。</p><hr><h2 id="第-1-课-docker-run-之后-宿主机上多了谁" tabindex="-1"><a class="header-anchor" href="#第-1-课-docker-run-之后-宿主机上多了谁"><span>第 1 课：docker run 之后，宿主机上多了谁</span></a></h2><p><strong>🧑‍🏫 老师：</strong></p><p>先不谈架构，直接动手。我这台机器上正跑着十几个容器，把 Docker 一家人的进程拍出来：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ps</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -eo</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> pid,ppid,args</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> | </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">grep</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -E</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &#39;dockerd|containerd|containerd-shim&#39;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> | </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">grep</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -v</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> grep</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>  506       1 /usr/bin/dockerd -H fd:// --containerd=/run/containerd/containerd.sock</span></span>
<span class="line"><span>  254       1 /usr/bin/containerd</span></span>
<span class="line"><span> 1016       1 /usr/bin/containerd-shim-runc-v2 -namespace moby -id 3bde51d700e2...</span></span>
<span class="line"><span> 1056       1 /usr/bin/containerd-shim-runc-v2 -namespace moby -id 79173ecc131c...</span></span>
<span class="line"><span> ...（每行一个 shim，共 13 个）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>先盯着最意外的一点：<strong>dockerd（506）和 containerd（254）的父进程都是 1 号</strong>，而且 containerd 的 PID 比 dockerd 还小——它比 dockerd 启动得还早。教材上那句「containerd 是 dockerd 拆出来的、挂在它下面」，在这台机器上不成立。这个疑点插问 1 专门拆。</p><p>现在请出本篇的主角容器，再顺着它把链路走一遍：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">docker</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> run</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -d</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --name</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> n23-lab</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> busybox</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> sleep</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 600</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">P</span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">$(</span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">docker</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> inspect</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -f</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &#39;{{.State.Pid}}&#39;</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> n23-lab</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>容器进程在宿主机上的真实 PID 是 <strong>84760</strong>。查它的爹，再查爹的爹：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>    PID    PPID COMMAND</span></span>
<span class="line"><span>  84760   84736 sleep 600                ← 容器内 PID 1（宿主侧真身）</span></span>
<span class="line"><span>  84736       1 /usr/bin/containerd-shim-runc-v2 -namespace moby -id 324690c6... -address /run/containerd/containerd.sock</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>两级就到头了：<strong>容器进程的爹是 shim，shim 的爹是 1 号</strong>——它不挂在 containerd 下面，更不挂在 dockerd 下面。</p><p>再验证「每容器一个 shim」：把所有 shim 的 <code>-id</code> 参数抽出来和运行中容器对账——本机 13 个运行容器、13 个 shim，一一对应，<code>-id</code> 后面跟的就是容器完整 ID（<code>docker inspect -f &#39;{{.Id}}&#39;</code> 逐字节相符）。</p><p>把冒出来的名字钉成一张图。注意这是<strong>调用关系</strong>，不是父子关系——刚才已经看到，真实的进程树比这张链扁平得多：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>docker（CLI）──&gt; dockerd ────&gt; containerd ──&gt; shim ──&gt; runc ──&gt; 容器进程</span></span>
<span class="line"><span>   发请求        管全局         管生命周期     每容器一个  动手创建  容器内 PID 1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>留两个悬念：dockerd 重启时，最底下那个 84760 会不会死？那排 shim 到底能不能杀？第 9 课一起解。</p><p>一句话总结本课：</p><blockquote><p><strong>容器进程的爹是 shim，不是 dockerd；shim 的 -id 就是容器完整 ID——这是把容器和宿主机进程对上号的最可靠钥匙。</strong></p></blockquote><hr><h2 id="插问-1-containerd-不是-dockerd-的孩子-教材是不是骗我" tabindex="-1"><a class="header-anchor" href="#插问-1-containerd-不是-dockerd-的孩子-教材是不是骗我"><span>插问 1：containerd 不是 dockerd 的孩子？教材是不是骗我</span></a></h2><p><strong>🧑‍🎓 学生：</strong> 你说第 1 课「最意外」，可我看的教程都画着 dockerd 下面挂着 containerd——到底谁对？为什么你这台机器上两个都直接挂在 1 号下面？</p><p><strong>🧑‍🏫 老师：</strong></p><p>两种画法都对，它们说的是<strong>不同的部署形态</strong>。看本机的证据链：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">systemctl</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> is-active</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> docker</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> containerd</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">grep</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> ExecStart</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /usr/lib/systemd/system/docker.service</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>active</span></span>
<span class="line"><span>active</span></span>
<span class="line"><span>ExecStart=/usr/bin/dockerd -H fd:// --containerd=/run/containerd/containerd.sock</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>两条 systemd 服务都是 active；dockerd 的启动命令里带着 <code>--containerd=/run/containerd/containerd.sock</code>——<strong>「containerd 我不自己生，我去连现成的」</strong>。装 Docker 引擎时同时装了 containerd 包，它注册成独立的 systemd 服务，开机自启、和 docker.service 平级，所以父进程都是 1 号、PID 还更小。教材上「dockerd 挂着 containerd」的画法对应 dockerd 自行拉起 containerd 的形态（不传那个旗标时它就这么干）。</p><p>但这只是<strong>出生方式的差异</strong>。两种形态下，谁跟谁说话完全一样，靠的都是 socket——把两个套接字摆出来：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ls</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -l</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /var/run/docker.sock</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /run/containerd/containerd.sock</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>/run/containerd/containerd.sock</span></span>
<span class="line"><span>/var/run/docker.sock</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>对应两级协议：CLI 敲 <code>docker ps</code>，请求进 <code>/var/run/docker.sock</code>（REST API，给 dockerd）；dockerd 要干活，经 <code>/run/containerd/containerd.sock</code>（gRPC，给 containerd）。第 1 课 shim 的参数里那个 <code>-address</code>，连的也是后者。</p><p>一句话收口：</p><blockquote><p><strong>进程树的父子关系是「谁生谁」，随部署形态变；socket 的调用关系是「谁跟谁说话」，永远不变——看架构看 socket，别只看进程树。</strong></p></blockquote><hr><h2 id="第-2-课-装一个-docker-来了一家人——daemon-三段演进" tabindex="-1"><a class="header-anchor" href="#第-2-课-装一个-docker-来了一家人——daemon-三段演进"><span>第 2 课：装一个 Docker，来了一家人——daemon 三段演进</span></a></h2><p><strong>🧑‍🏫 老师：</strong></p><p>第 1 课树上的名字，来历是一段拆分史。Docker 守护进程从早期集成在 <code>docker</code> 命令中，逐步独立：</p><table><thead><tr><th>版本</th><th>启动命令</th><th>形态</th></tr></thead><tbody><tr><td>Docker 1.8 之前</td><td><code>docker -d</code></td><td>守护进程是 client 的一个选项</td></tr><tr><td>Docker 1.8</td><td><code>docker daemon</code></td><td>守护进程是 docker 命令的模块</td></tr><tr><td>Docker 1.11+</td><td><code>dockerd</code></td><td><strong>独立二进制</strong>，与 client 分离</td></tr></tbody></table><p>也是在 1.11（2016）这版，容器执行链被拆出 containerd 和 runc——<strong>「五级接力」的格局就是这时定型的</strong>。老教程里 <code>docker -d</code>、<code>docker daemon</code> 两种写法早已废弃，看到别照抄。</p><p>现在这家人在本机的合影（<code>ls -l /usr/bin/...</code>）：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>/usr/bin/docker                    31 MB   # CLI 客户端</span></span>
<span class="line"><span>/usr/bin/dockerd                   84 MB   # 守护进程</span></span>
<span class="line"><span>/usr/bin/containerd                48 MB   # 容器运行时（中间层）</span></span>
<span class="line"><span>/usr/bin/containerd-shim-runc-v2    8 MB   # 容器垫片</span></span>
<span class="line"><span>/usr/bin/runc                      11 MB   # OCI 运行时实现</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>五个二进制正好对上第 1 课那棵树——装一个 Docker 引擎，来的其实是一家人，各有各的岗位。接下来每课拜访一位。</p><p>一句话总结本课：</p><blockquote><p><strong><code>docker -d</code> → <code>docker daemon</code> → <code>dockerd</code> 三代写法是历史；今天 <code>/usr/bin</code> 里站着的是一家人，各司其职。</strong></p></blockquote><hr><h2 id="第-3-课-第一只手-cli——只发请求-不建容器" tabindex="-1"><a class="header-anchor" href="#第-3-课-第一只手-cli——只发请求-不建容器"><span>第 3 课：第一只手 CLI——只发请求，不建容器</span></a></h2><p><strong>🧑‍🏫 老师：</strong></p><p>你在终端敲 <code>docker run -d busybox sleep 600</code>，<code>docker</code> 这个程序只做三件事：解析参数、组一个 REST 请求、发给 <code>/var/run/docker.sock</code> 另一头的 dockerd。<strong>请求发完，CLI 进程就退出了。</strong></p><p>这解释了第 1 课进程树里一个「缺席者」：树里根本没有 docker CLI——它不是常驻进程。几个直接推论：</p><ul><li>关掉终端、CLI 崩掉，容器照跑（容器跟 CLI 没有进程关系）；</li><li>把客户端装在另一台机器上、用 <code>DOCKER_HOST=tcp://宿主:2375</code> 指过来，一样能管容器——CLI 和 daemon 天生可分离，这也是 daemon 远程管理与 TLS 加密的入口（<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-28-daemon-ops">第 28 篇</a>）；</li><li>所以「Docker 客户端」升级（那 31MB）从不影响正在跑的容器——换的只是发令的嘴。</li></ul><p>一句话总结本课：</p><blockquote><p><strong>CLI 是发令的，不是干活的——它连进程树都不进，凭什么影响容器生死？</strong></p></blockquote><hr><h2 id="第-4-课-第二只手-dockerd——接单、记账、派活" tabindex="-1"><a class="header-anchor" href="#第-4-课-第二只手-dockerd——接单、记账、派活"><span>第 4 课：第二只手 dockerd——接单、记账、派活</span></a></h2><p><strong>🧑‍🏫 老师：</strong></p><p>CLI 的请求打到 dockerd。它的职责四条，翻成白话就是「接单、记账、派活、挡变化」：</p><ol><li><strong>接单</strong>：开着 API 服务等请求（那个 socket 的另一头）；</li><li><strong>记账</strong>：镜像、网络（<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-15-network">第 15 篇</a>的 bridge）、卷（<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-14-data-persistence">第 14 篇</a>）这些「资产」都归它管——<code>docker ps</code>、<code>docker images</code> 的答案从这来；</li><li><strong>派活</strong>：真正创建容器进程这步<strong>不亲自干</strong>，经 gRPC 派给 containerd；</li><li><strong>挡变化</strong>：底层 runtime 换版本甚至换实现，对外 API 不变——你手里的 docker 命令不用跟着改。</li></ol><p>管的事多，daemon 就重。本机实测它攥着多少家当：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ls</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /proc/</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">$(</span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">pidof</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> dockerd</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">)</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">/fd</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> | </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">wc</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -l</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>135</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>135 个打开的文件句柄——镜像层、容器元数据、日志、网络、卷，账本都在它手里。daemon 越重，重启的代价越大：<strong>重启那几十秒里，<code>docker ps</code> 都没人回答</strong>。这就是「daemon 重启容器死不死」让人紧张的原因——第 9 课给完整答案，先记一个官方开关的名字：<code>live-restore</code>（本机 <code>docker info</code> 显示 <code>Live Restore Enabled: false</code>，默认关着，<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-28-daemon-ops">第 28 篇</a>落地它）。</p><p>一句话总结本课：</p><blockquote><p><strong>dockerd 是账房先生：什么都在它账上，但容器进程不是它的孩子——账本丢了可以重建，人（进程）不用死。</strong></p></blockquote><hr><h2 id="第-5-课-先签合同——oci-与-filesystem-bundle" tabindex="-1"><a class="header-anchor" href="#第-5-课-先签合同——oci-与-filesystem-bundle"><span>第 5 课：先签合同——OCI 与 filesystem bundle</span></a></h2><p><strong>🧑‍🏫 老师：</strong></p><p>dockerd 派活、containerd 接活、runc 干活，三层来自不同的项目，凭什么能互相配合？因为动手之前先签了份合同。</p><p>设想没有标准的世界：每家容器引擎的镜像格式、启动方式都是私有的——A 家构建的镜像 B 家跑不了，K8s 想换 runtime 就得整套重写。所以 2015 年 Docker、CoreOS 等公司共同发起 <strong>OCI</strong>（Open Container Initiative，开放容器倡议），制定容器<strong>镜像格式</strong>与<strong>运行时</strong>的开放标准，并维护参考实现 runc。</p><p>合同不用背——<strong>在本机就能打印一份原件</strong>。runc 自带 <code>spec</code> 子命令，生成标准模板：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">mkdir</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /tmp/runc23</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;&amp; </span><span style="--shiki-light:#0184BC;--shiki-dark:#56B6C2;">cd</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /tmp/runc23</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;&amp; </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">runc</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> spec</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;&amp; </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">head</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -c</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 160</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> config.json</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-json line-numbers-mode" data-highlighter="shiki" data-ext="json" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-json"><span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">{</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">	&quot;ociVersion&quot;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">: </span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">&quot;1.2.1&quot;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">,</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">	&quot;process&quot;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">: {</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">		&quot;terminal&quot;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">: </span><span style="--shiki-light:#0184BC;--shiki-dark:#D19A66;">true</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">,</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">		&quot;user&quot;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">: { </span><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">&quot;uid&quot;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">: </span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;">0</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">, </span><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">&quot;gid&quot;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">: </span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;">0</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> },</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">		&quot;args&quot;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">: [ </span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">&quot;sh&quot;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> ],</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">		&quot;env&quot;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">: [ </span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">&quot;PATH=/usr/local/sb...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这份 <code>config.json</code> 就是合同的下半页原文：版本号、跑什么（args）、什么身份（uid/gid）、什么环境（env）…… OCI 用 <strong>filesystem bundle</strong>（文件系统包）这个标准格式把合同两页接起来：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>image-spec（镜像长什么样）</span></span>
<span class="line"><span>        │  解包（unpack）：镜像 → bundle</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>bundle = 一个目录：rootfs + config.json</span></span>
<span class="line"><span>        │  runtime 读懂 bundle</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>runtime-spec（容器怎么跑：状态 + 操作）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>一句话总结本课：</p><blockquote><p><strong>合同两页：image-spec 管镜像长什么样，runtime-spec 管容器怎么跑；<code>runc spec</code> 一条命令把合同打印给你看。</strong></p></blockquote><hr><h2 id="第-6-课-合同上半页——image-spec-里装了什么" tabindex="-1"><a class="header-anchor" href="#第-6-课-合同上半页——image-spec-里装了什么"><span>第 6 课：合同上半页——image-spec 里装了什么</span></a></h2><p><strong>🧑‍🏫 老师：</strong></p><p>OCI 镜像四件套，拿本机 busybox 逐个对：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">docker</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> image</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> inspect</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> busybox</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -f</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &#39;layers={{len .RootFS.Layers}} env={{.Config.Env}} cmd={{.Config.Cmd}}&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>layers=1 env=[PATH=/usr/local/sbin:...] cmd=[sh]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><table><thead><tr><th>组件</th><th>说明</th><th>对应</th></tr></thead><tbody><tr><td><strong>layers</strong></td><td>每层存「相对上层的改动」，层带 hash 可共享</td><td>busybox 就 1 层；<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-22-unionfs">第 22 篇</a>把它们叠成 rootfs</td></tr><tr><td><strong>config</strong></td><td>环境变量、工作目录、CMD</td><td>上面那行 env/cmd 就是它的内容——<code>docker inspect &lt;镜像&gt;</code> 打的这份</td></tr><tr><td><strong>manifest</strong></td><td>指明用哪份 config、拉哪些层</td><td>「提货单」</td></tr><tr><td><strong>index</strong>（可选）</td><td>跨平台清单</td><td>一个 tag 里装着 amd64/arm64 多份 manifest</td></tr></tbody></table><p>index 这件我在本机没演示成：<code>docker manifest inspect busybox</code> 要直连 registry，本机走镜像加速、到 <a href="http://registry-1.docker.io" target="_blank" rel="noopener noreferrer">registry-1.docker.io</a> 超时——多平台的实操在<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-11-buildx-bake">第 11 篇 buildx</a>，那里专门构建 amd64+arm64 双平台镜像。读完这节，<code>docker pull</code> 刷出来的「一串 hash 层 + 一份清单」各是什么角色，你都能对号入座。</p><p>一句话总结本课：</p><blockquote><p><strong>镜像 = layers（可共享的积木）+ config（出厂设置）+ manifest（提货单）+ index（多平台目录）。</strong></p></blockquote><hr><h2 id="第-7-课-合同下半页——runtime-spec-状态机-docker-create-亲眼见" tabindex="-1"><a class="header-anchor" href="#第-7-课-合同下半页——runtime-spec-状态机-docker-create-亲眼见"><span>第 7 课：合同下半页——runtime-spec 状态机，docker create 亲眼见</span></a></h2><p><strong>🧑‍🏫 老师：</strong></p><p>runtime-spec 规定容器的<strong>状态</strong>和 runtime 必须会做的<strong>动作</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>creating → created → running → stopped</span></span>
<span class="line"><span>                ↘         ↗</span></span>
<span class="line"><span>                  paused</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键是 <strong>create 和 start 分成两步</strong>——<code>create</code> 只把容器「造」出来（namespace、cgroup、rootfs 就位，用户进程没跑），<code>start</code> 才把 init 进程拉起来。这不只是规范条文，Docker 的命令行直接把它暴露给你：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">docker</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> create</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --name</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> n23-ghost</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> busybox</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> sleep</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 600</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">docker</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> ps</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -a</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --filter</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> name=n23-ghost</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --format</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &#39;{{.Names}} {{.Status}}&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>eb5ab57babde...</span></span>
<span class="line"><span>n23-ghost Created        ← 状态机的 created 节点，实物</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>容器造好了、没启动——正是「配置就位但进程未跑」的检查点。再补一刀：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">docker</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> start</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> n23-ghost</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">docker</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> ps</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --filter</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> name=n23-ghost</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --format</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &#39;{{.Names}} {{.Status}}&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>n23-ghost Up Less than a second    ← created → running</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>docker ps</code> 里的 Created / Up / Exited，底层说的就是这套状态机的语言（paused 对应 <code>docker pause</code>，用的正是<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-21-cgroups">第 21 篇</a>讲过的 freezer 思路）。</p><p>一句话总结本课：</p><blockquote><p><strong>状态机不是纸面概念：<code>docker create</code> 停在 created，<code>docker start</code> 才进 running——两步之间的容器，是一个「造好没通电」的检查点。</strong></p></blockquote><hr><h2 id="第-8-课-第三只手-containerd——独立的大管家" tabindex="-1"><a class="header-anchor" href="#第-8-课-第三只手-containerd——独立的大管家"><span>第 8 课：第三只手 containerd——独立的大管家</span></a></h2><p><strong>🧑‍🏫 老师：</strong></p><p>第 1 课插问里已经看到它在独立服务里活着。职责三条：<strong>镜像管理</strong>（pull、unpack、snapshot——第 5 课模型里「镜像 → bundle」那步是它干的）、<strong>容器执行</strong>（派 shim、用 runc）、<strong>即使 dockerd 不在也能管容器</strong>（需相应 CLI）。</p><p>最后这条本机可以直接演示——containerd 自带的 CLI 叫 <code>ctr</code>，从<strong>containerd 的视角</strong>看这台机器：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ctr</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -n</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> moby</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> containers</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> list</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> | </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">head</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -3</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>CONTAINER                                                           IMAGE</span></span>
<span class="line"><span>06136fab34de...                                                    docker.io/calciumion/n...</span></span>
<span class="line"><span>324690c63e47...                                                    docker.io/library/busybox:latest</span></span>
<span class="line"><span>3bde51d700e2...                                                    docker.io/library/redis...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>两件事值得盯：第二行 <code>324690c6...</code> 正是我的 n23-lab——<strong>dockerd 记的账和 containerd 记的账，说的是同一个容器</strong>；而 <code>-n moby</code> 这个参数是关键——Docker 在 containerd 里占的命名空间叫 <strong>moby</strong>（Docker 上游项目名），K8s 的 kubelet 走的是 <code>k8s.io</code> 命名空间——<strong>同一台机器、同一个 containerd，两套账本互不打架</strong>。单独装 containerd、用 <code>ctr</code> 从 pull 一路跑到 exec 的完整实操在附篇 <a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-a02-containerd">a02</a>。</p><p>一句话总结本课：</p><blockquote><p><strong>containerd 是独立大管家：dockerd 只是它的客户之一；moby/k8s.io 两个命名空间，就是 Docker 和 K8s 在同一管家处的两个账户。</strong></p></blockquote><hr><h2 id="插问-2-容器跑起来之后-磁盘上留了什么运行时档案" tabindex="-1"><a class="header-anchor" href="#插问-2-容器跑起来之后-磁盘上留了什么运行时档案"><span>插问 2：容器跑起来之后，磁盘上留了什么运行时档案？</span></a></h2><p><strong>🧑‍🎓 学生：</strong> 你说 bundle = rootfs + config.json——那我这个正在跑的 n23-lab，bundle 在哪？能看到实物吗？</p><p><strong>🧑‍🏫 老师：</strong></p><p>能，而且这页档案信息量极大。containerd 为每个容器开的任务目录在 <code>/run/containerd</code> 下，目录名就是容器完整 ID：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">CID</span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">$(</span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">docker</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> inspect</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -f</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &#39;{{.Id}}&#39;</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> n23-lab</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">)</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ls</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /run/containerd/io.containerd.runtime.v2.task/moby/</span><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">$CID</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">/</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>bootstrap.json  config.json  init.pid  log  log.json</span></span>
<span class="line"><span>options.json    rootfs       runtime   shim-binary-path  work</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>三样要认：</p><ol><li><strong><code>config.json</code></strong>——第 5 课那份合同原件的真实副本，头几个字段：<code>{&quot;ociVersion&quot;:&quot;1.2.1&quot;,&quot;process&quot;:{&quot;args&quot;:[&quot;sleep&quot;,&quot;600&quot;],...}}</code>——<strong>版本号和 runc 自报的 spec 1.2.1 一致，args 就是我起的 <code>sleep 600</code></strong>。这份文件就是 runc 创建容器时照着执行的说明书。</li><li><strong><code>init.pid</code></strong>——里面一个数字：<code>84760</code>。跟 <code>docker inspect -f &#39;{{.State.Pid}}&#39;</code> 对，分毫不差。<strong>容器 1 号进程在宿主机上的 PID，白纸黑字记在档案里</strong>。</li><li><strong><code>rootfs/</code></strong>——<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-22-unionfs">第 22 篇</a>叠出来的根文件系统挂在这；<code>log</code> 系列是 shim 替容器收着的输出（<code>docker logs</code> 的源头）。</li></ol><p>一句话收口：</p><blockquote><p><strong>一个运行中的容器 = 一个任务目录：config.json 是出生证明、init.pid 是真身住址、rootfs 是身体、log 是日记——全在 <code>/run/containerd</code> 下可查。</strong></p></blockquote><hr><h2 id="第-9-课-第四只手-shim——陪跑的保姆-与那个悬念的答案" tabindex="-1"><a class="header-anchor" href="#第-9-课-第四只手-shim——陪跑的保姆-与那个悬念的答案"><span>第 9 课：第四只手 shim——陪跑的保姆，与那个悬念的答案</span></a></h2><p><strong>🧑‍🏫 老师：</strong></p><p>每启动<strong>一个容器</strong>，就多<strong>一个</strong> shim（第 1 课对过账：13 容器 13 shim）。它的启动参数三项，第 1 课抓的实拍逐个对：</p><ul><li><code>-namespace moby</code>：在 containerd 的哪个账户下（接第 8 课）；</li><li><code>-id 324690c6...</code>：容器完整 ID——对容器和 shim 的钥匙；</li><li><code>-address /run/containerd/containerd.sock</code>：向谁汇报工作。</li></ul><p>shim 拿到任务后拼装 <code>runc create</code> / <code>runc start</code> 两条命令（正好踩在第 7 课状态机的两个节点上），然后接管余生。<strong>存在的三大意义</strong>：</p><ol><li><strong>runc 可退出</strong>：创建完容器 runc 就走，不必每个容器养一个常驻 runtime；</li><li><strong>IO 保活</strong>：容器的 stdin/stdout/stderr 由 shim 扛着——插问 2 任务目录里那些 log 文件就是实体——即使 daemon 全挂，容器输出不断流；</li><li><strong>上报退出状态</strong>：容器退出时把 exit code 报给 containerd。</li></ol><p>第 1 条当场验证——13 个容器跑着，宿主机上找 runc 进程：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">pgrep</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -x</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> runc</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> | </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">wc</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -l</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>零个</strong>。runc 是一次性工具，干完就走（这也是为什么直接拿 <code>runc list</code> 查 Docker 的容器会报 <code>container does not exist</code>——台账在 shim 手里，runc 早退场了）。</p><p>顺手再做一次诚实记录：我试过 <code>runc --root &lt;任务目录&gt; list</code> 想看它的台账，报了一排 <code>load container ...: does not exist</code>——shim v2 时代 runc 不留传统状态文件，这次失败本身就是「runc 是临时工」的证据。</p><p>现在解开头两个悬念。<strong>dockerd 重启，容器死不死？</strong> 看第 1 课的树：容器进程（84760）的爹是 shim（84736），shim 的爹是 1 号；shim 只认 containerd 的 socket，根本不知道 dockerd 的死活；runc 更是早退场了。所以<strong>结构上，这条链没有任何一环攥在 dockerd 手里</strong>——dockerd 崩了（kill -9），shim 带着容器原地不动。但注意边界：<code>systemctl restart docker</code> 是<strong>优雅关闭</strong>，默认（本机 <code>Live Restore Enabled: false</code>）dockerd 退出前会主动停掉容器——容器活不活取决于「怎么个重启法」，生产上要保容器得开 <code>live-restore</code>，这是 <a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-28-daemon-ops">第 28 篇</a>的主课。<strong>那排 shim 能不能杀？</strong> 现在你自己能推出来：杀 shim = 杀掉容器的监护人和 IO 管道，容器跟着完——它看着像杂鱼，其实是命脉。</p><p>一句话总结本课：</p><blockquote><p><strong>shim 是陪跑保姆：runc 干完就走、IO 由它扛、exit code 由它报——daemon 的死活在结构上与容器无关，但优雅重启的清场行为除外。</strong></p></blockquote><hr><h2 id="第-10-课-第五只手-runc-与全景拼图" tabindex="-1"><a class="header-anchor" href="#第-10-课-第五只手-runc-与全景拼图"><span>第 10 课：第五只手 runc，与全景拼图</span></a></h2><p><strong>🧑‍🏫 老师：</strong></p><p>链路走到底才轮到真正碰内核的这位。runc 从 Docker 的 libcontainer 迁移而来，负责：容器创建/启动/删除、<strong>Namespace 隔离</strong>（<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-20-namespace">第 20 篇</a>六大件全是它设置的）、<strong>Cgroup 限额</strong>（<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-21-cgroups">第 21 篇</a>的枷锁是它给容器戴上的）。前面四只手都没碰过内核；到 runc，才真正执行那些系统调用。</p><p>本机版本自报家门：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">runc</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --version</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> | </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">head</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -2</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>runc version 1.3.4-0ubuntu1~22.04.1</span></span>
<span class="line"><span>spec: 1.2.1      ← 它实现的 runtime-spec 版本</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>只要守合同就能换人：<code>dockerd --add-runtime &quot;custom=/path/to/别的实现&quot;</code> 注册替代 runtime——gVisor、Kata 这类安全沙箱 runtime 走的就是这条路（分类见附篇 <a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-a01-container-runtime-docker">a01</a>）。</p><p>十课攒下的名字，按调用顺序摆进全景图：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│  docker     │  CLI：发 REST 请求，非常驻</span></span>
<span class="line"><span>└──────┬──────┘</span></span>
<span class="line"><span>       ▼ /var/run/docker.sock</span></span>
<span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│  dockerd    │  接单、记账（镜像/网络/卷）、挡变化</span></span>
<span class="line"><span>└──────┬──────┘</span></span>
<span class="line"><span>       ▼ /run/containerd/containerd.sock（gRPC）</span></span>
<span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│ containerd  │  unpack bundle、派 shim、管生命周期</span></span>
<span class="line"><span>└──────┬──────┘</span></span>
<span class="line"><span>       ▼ 每容器一个</span></span>
<span class="line"><span>┌─────────────────────┐</span></span>
<span class="line"><span>│ containerd-shim     │  拼runc命令、扛IO、报exit code</span></span>
<span class="line"><span>└──────┬──────────────┘</span></span>
<span class="line"><span>       ▼ runc create / start（干完即退）</span></span>
<span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│    runc     │  设 namespace + cgroup，创建容器进程</span></span>
<span class="line"><span>└──────┬──────┘</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│ 容器内进程   │  sleep 600 / nginx / your-app（PID 1）</span></span>
<span class="line"><span>└─────────────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>顺着图把 <code>docker run -d busybox sleep 600</code> 走一遍：CLI 发请求 → dockerd 记账派活 → containerd unpack 出 bundle、派 shim → shim 拼 <code>runc create</code>/<code>start</code> → runc 设好 namespace/cgroup 创建出 84760 然后退出 → 此后陪着容器的只有 shim。<strong>每一级的联系方式都是 socket，每一级都可以独立替换</strong>——这就是「五级接力」的全部。</p><p>一句话总结本课：</p><blockquote><p><strong>CLI 发令、dockerd 记账、containerd 管家、shim 陪跑、runc 动手——五级靠 socket 相连，靠 OCI 合同配合。</strong></p></blockquote><hr><h2 id="插问-3-「k8s-抛弃了-docker」-我-docker-构建的镜像还能在-k8s-上跑吗" tabindex="-1"><a class="header-anchor" href="#插问-3-「k8s-抛弃了-docker」-我-docker-构建的镜像还能在-k8s-上跑吗"><span>插问 3：「K8s 抛弃了 Docker」，我 Docker 构建的镜像还能在 K8s 上跑吗？</span></a></h2><p><strong>🧑‍🎓 学生：</strong> 都说 K8s 1.24 抛弃了 Docker——那我用 <code>docker build</code> 打的镜像，上了 K8s 集群还能跑吗？</p><p><strong>🧑‍🏫 老师：</strong></p><p>能跑，而且这句话本身就只对了一半。K8s 与 Docker 的关系三段演进：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>早期 K8s</span></span>
<span class="line"><span>  kubelet → 对接 Docker 的代码写死在 kubelet 里</span></span>
<span class="line"><span></span></span>
<span class="line"><span>K8s 1.5+ 推出 CRI（Container Runtime Interface）</span></span>
<span class="line"><span>  kubelet → CRI → dockershim（翻译层，K8s 社区维护）→ dockerd → containerd → shim → runc</span></span>
<span class="line"><span></span></span>
<span class="line"><span>K8s 1.24+ 移除 dockershim</span></span>
<span class="line"><span>  kubelet → CRI → containerd（内置 CRI 插件）→ shim → runc</span></span>
<span class="line"><span>  或：kubelet → CRI → CRI-O → runc</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>读三段：早期对接代码写死，runtime 一换 kubelet 就得改源码——所以 1.5 起有了 <strong>CRI</strong> 这个统一接口；Docker 当时没实现 CRI，K8s 只好自己维护一个<strong>dockershim</strong> 翻译层（CRI → Docker API），白白多一层、还是 K8s 社区替 Docker 打工；1.24 起 K8s 删掉 dockershim，走 containerd 内置的 CRI 插件或 CRI-O 直连。</p><p>所以「抛弃」掉的只是 <strong>dockershim 这层翻译</strong>，不是 Docker 的镜像——因为镜像格式走的是第 6 课那份 <strong>OCI image-spec 合同</strong>，containerd/CRI-O 都认。两个缩写别再混：</p><table><thead><tr><th>名字</th><th>是什么</th><th>给谁用</th></tr></thead><tbody><tr><td><strong>OCI</strong></td><td>镜像格式 + 运行时行为的标准（image-spec / runtime-spec）</td><td>所有容器工具的「普通话」</td></tr><tr><td><strong>CRI</strong></td><td>kubelet 与 runtime 之间的接口，带 Pod / PodSandbox 语义</td><td>Kubernetes 的「方言」</td></tr></tbody></table><p>一句话收口：</p><blockquote><p><strong>K8s 抛弃的是 dockershim 翻译层，不是 OCI 镜像——你 Docker 构建的镜像在任何 OCI runtime 上照跑，合同还在生效。</strong></p></blockquote><hr><h2 id="命令速查" tabindex="-1"><a class="header-anchor" href="#命令速查"><span>命令速查</span></a></h2><table><thead><tr><th>想看什么</th><th>命令</th><th>哪课用过</th></tr></thead><tbody><tr><td>家族进程合影</td><td><code>ps -eo pid,ppid,args | grep -E &#39;dockerd|containerd&#39;</code></td><td>1</td></tr><tr><td>容器真身与爹链</td><td><code>docker inspect -f &#39;{{.State.Pid}}&#39;</code> + <code>ps -o pid,ppid,args -p</code></td><td>1</td></tr><tr><td>shim 对容器</td><td>shim 参数 <code>-id</code> vs <code>docker inspect .Id</code></td><td>1、9</td></tr><tr><td>daemon 怎么起的</td><td><code>grep ExecStart /usr/lib/systemd/system/docker.service</code></td><td>插问 1</td></tr><tr><td>daemon 有多重</td><td><code>ls /proc/$(pidof dockerd)/fd | wc -l</code></td><td>4</td></tr><tr><td>合同原件</td><td><code>runc spec</code>（生成 config.json 模板）</td><td>5</td></tr><tr><td>状态机两步</td><td><code>docker create</code> → <code>docker start</code></td><td>7</td></tr><tr><td>containerd 视角</td><td><code>ctr -n moby containers list</code></td><td>8</td></tr><tr><td>运行时档案</td><td><code>ls /run/containerd/io.containerd.runtime.v2.task/moby/&lt;cid&gt;/</code></td><td>插问 2</td></tr><tr><td>runc 是否常驻</td><td><code>pgrep -x runc | wc -l</code>（跑着容器时=0）</td><td>9</td></tr></tbody></table><hr><h2 id="小结" tabindex="-1"><a class="header-anchor" href="#小结"><span>小结</span></a></h2><ol><li><strong>进程树（第 1 课）</strong>：容器进程的爹是 shim；本机 dockerd/containerd/shim 都直挂 1 号——父子关系随部署形态变，调用关系看 socket。</li><li><strong>一家人（第 2 课）</strong>：<code>docker -d</code> → <code>dockerd</code> 三代演进；<code>/usr/bin</code> 五个二进制各司其职。</li><li><strong>CLI（第 3 课）</strong>：只发 REST 请求，非常驻；<code>DOCKER_HOST</code> 可远程。</li><li><strong>dockerd（第 4 课）</strong>：接单、记账（本机 135 个 fd）、派活、挡变化；<code>live-restore</code> 默认关。</li><li><strong>OCI（第 5 课）</strong>：合同两页 + bundle；<code>runc spec</code> 打印原件。</li><li><strong>image-spec（第 6 课）</strong>：layers + config + manifest（+ index 多平台）。</li><li><strong>runtime-spec（第 7 课）</strong>：状态机 creating→created→running→stopped；<code>docker create</code> 亲眼停在 created。</li><li><strong>containerd（第 8 课）</strong>：独立服务、moby 命名空间；<code>ctr -n moby</code> 第二本账。</li><li><strong>运行时档案（插问 2）</strong>：任务目录里 config.json / init.pid / rootfs / log——出生证明与真身住址。</li><li><strong>shim（第 9 课）</strong>：runc 可退（实测 0 常驻）、IO 保活、报 exit code；daemon 崩溃容器不死，优雅重启另说。</li><li><strong>runc 与全景（第 10 课）</strong>：碰内核的只有它；五级靠 socket 相连、靠 OCI 合同配合。</li><li><strong>CRI（插问 3）</strong>：K8s 弃用的是 dockershim 翻译层，OCI 镜像照跑。</li></ol><p><strong>思考题</strong>：生产机 <code>systemctl restart docker</code> 后容器全停了，同事说「你不是讲过容器不归 dockerd 管吗」——你该向他解释哪两个概念的差别？（提示：第 9 课「结构上不攥命」与「优雅关闭主动清场」；解药叫什么、默认开没开？）</p><p>下一篇：<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-24-process-view">《进程视角看容器——从两边 ps 对不上号，滚到亲手杀掉 PID 1》</a>——本篇的 84760 和 84736，到那边要亲手抓出来、亲手杀掉。</p><hr><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://opencontainers.org/" target="_blank" rel="noopener noreferrer">OCI 官网与规范索引</a>、<a href="https://github.com/opencontainers/image-spec" target="_blank" rel="noopener noreferrer">image-spec</a> / <a href="https://github.com/opencontainers/runtime-spec" target="_blank" rel="noopener noreferrer">runtime-spec</a></li><li><a href="https://github.com/opencontainers/runc" target="_blank" rel="noopener noreferrer">runc（OCI 参考实现）</a>——<code>runc spec</code> 生成合同模板</li><li><a href="https://containerd.io/" target="_blank" rel="noopener noreferrer">containerd 官网</a> 与 <a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-a02-containerd">ctr/containerd 实操附篇</a></li><li><a href="https://docs.docker.com/engine/" target="_blank" rel="noopener noreferrer">Docker Engine 文档</a>、<a href="https://docs.docker.com/engine/daemon/live-restore/" target="_blank" rel="noopener noreferrer">live-restore</a>（第 28 篇落地）</li><li><a href="https://kubernetes.io/docs/concepts/architecture/cri/" target="_blank" rel="noopener noreferrer">Kubernetes Container Runtimes（CRI）</a></li><li>本机实测：WSL2 Ubuntu-22.04 · Docker 29.1.3 · containerd（独立 systemd 服务）· runc 1.3.4（spec 1.2.1），实测日期 2026-08-25</li></ul>`,178)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};